/** Job types, request validation, idempotency keys, and the public job shape. */

export const JOB_STATUSES = ['queued', 'running', 'completed', 'failed'] as const;
export type JobStatus = (typeof JOB_STATUSES)[number];

export const MAX_INPUT_LENGTH = 1000;
export const STEPS = { min: 1, max: 20, default: 5 } as const;
export const FAIL_ATTEMPTS = { min: 0, max: 5, default: 0 } as const;

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

/** A validated submission, with defaults applied. */
export interface NewJobPayload {
  input: string;
  steps: number;
  failAttempts: number;
}

/** A job as stored in SQLite, in internal camelCase form. */
export interface JobRecord {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  completedSteps: number;
  output: string | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
  availableAt: number;
  idemKey: string | null;
  idemPayload: string | null;
}

export interface FieldError {
  field: string;
  message: string;
}

/** The job shape returned by every endpoint. */
export interface PublicJob {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

function checkInteger(
  obj: Record<string, unknown>,
  name: 'steps' | 'failAttempts',
  range: { min: number; max: number; default: number },
  fields: FieldError[],
): number | undefined {
  if (!Object.hasOwn(obj, name)) return range.default;
  const v = obj[name];
  if (typeof v === 'number' && Number.isInteger(v) && v >= range.min && v <= range.max) return v;
  fields.push({ field: name, message: `${name} must be an integer from ${range.min} to ${range.max}` });
  return undefined;
}

/** Validates a parsed request body. Returns `value` only when there are no errors. */
export function validatePayload(body: unknown): { value?: NewJobPayload; fields: FieldError[] } {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    return { fields: [{ field: 'body', message: 'body must be a JSON object' }] };
  }
  const obj = body as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input: string | undefined;
  if (!Object.hasOwn(obj, 'input')) {
    fields.push({ field: 'input', message: 'input is required' });
  } else {
    const v = obj.input;
    if (typeof v === 'string' && v.length <= MAX_INPUT_LENGTH && v.trim() !== '') input = v;
    else fields.push({ field: 'input', message: `input must be a string of 1 to ${MAX_INPUT_LENGTH} characters that is not only whitespace` });
  }

  const steps = checkInteger(obj, 'steps', STEPS, fields);
  const failAttempts = checkInteger(obj, 'failAttempts', FAIL_ATTEMPTS, fields);

  if (fields.length > 0 || input === undefined || steps === undefined || failAttempts === undefined) {
    return { fields };
  }
  return { value: { input, steps, failAttempts }, fields };
}

/** Validates an Idempotency-Key header value. An absent header yields `key: null`. */
export function parseIdempotencyKey(header: string | string[] | undefined): { key: string | null; error?: FieldError } {
  if (header === undefined) return { key: null };
  if (typeof header === 'string' && IDEMPOTENCY_KEY_PATTERN.test(header)) return { key: header };
  return { key: null, error: { field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$' } };
}

/** Canonical form of a validated payload, used to compare idempotent replays. */
export function canonicalPayload(p: NewJobPayload): string {
  return JSON.stringify({ input: p.input, steps: p.steps, failAttempts: p.failAttempts });
}

/** Converts a stored job into the public JSON shape. */
export function serializeJob(job: JobRecord): PublicJob {
  return {
    id: job.id,
    status: job.status,
    input: job.input,
    steps: job.steps,
    failAttempts: job.failAttempts,
    attempts: job.attempts,
    progress: { completed: job.completedSteps, total: job.steps },
    result: job.status === 'completed' && job.output !== null ? { output: job.output } : null,
    error: job.status === 'failed' ? job.error : null,
    createdAt: job.createdAt,
    updatedAt: job.updatedAt,
  };
}

