import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import type { JobRecord, JobStatus } from './jobs.ts';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed_steps INTEGER NOT NULL DEFAULT 0,
  output TEXT,
  error TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  available_at INTEGER NOT NULL,
  idem_key TEXT UNIQUE,
  idem_payload TEXT
);
CREATE INDEX IF NOT EXISTS jobs_claim ON jobs (status, available_at, seq);
CREATE TABLE IF NOT EXISTS worker_state (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  heartbeat_at INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

/** Runs `fn` in a write transaction. Keep `fn` synchronous and short. */
export function withImmediateTransaction<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (err) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // no transaction is open
    }
    throw err;
  }
  return result;
}

interface JobRow {
  seq: number;
  id: string;
  status: string;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed_steps: number;
  output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
  available_at: number;
  idem_key: string | null;
  idem_payload: string | null;
}

function toRecord(r: JobRow): JobRecord {
  return {
    seq: r.seq,
    id: r.id,
    status: r.status as JobStatus,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    completedSteps: r.completed_steps,
    output: r.output,
    error: r.error,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
    availableAt: r.available_at,
    idemKey: r.idem_key,
    idemPayload: r.idem_payload,
  };
}

function one(db: DatabaseSync, sql: string, ...params: (string | number | null)[]): JobRow | undefined {
  return db.prepare(sql).get(...params) as unknown as JobRow | undefined;
}

export function findJobById(db: DatabaseSync, id: string): JobRecord | undefined {
  const row = one(db, 'SELECT * FROM jobs WHERE id = ?', id);
  return row && toRecord(row);
}

export function findJobByIdemKey(db: DatabaseSync, key: string): JobRecord | undefined {
  const row = one(db, 'SELECT * FROM jobs WHERE idem_key = ?', key);
  return row && toRecord(row);
}

export function listJobs(db: DatabaseSync): JobRecord[] {
  return (db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[]).map(toRecord);
}

export function insertJob(db: DatabaseSync, job: JobRecord): void {
  db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed_steps, output, error,
                       created_at, updated_at, available_at, idem_key, idem_payload)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  ).run(
    job.id,
    job.status,
    job.input,
    job.steps,
    job.failAttempts,
    job.attempts,
    job.completedSteps,
    job.output,
    job.error,
    job.createdAt,
    job.updatedAt,
    job.availableAt,
    job.idemKey,
    job.idemPayload,
  );
}

export function writeHeartbeat(db: DatabaseSync, nowMs: number): void {
  db.prepare(
    'INSERT INTO worker_state (id, heartbeat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET heartbeat_at = excluded.heartbeat_at',
  ).run(nowMs);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.exec('DELETE FROM worker_state');
}

export function readHeartbeat(db: DatabaseSync): number | undefined {
  const row = db.prepare('SELECT heartbeat_at FROM worker_state WHERE id = 1').get() as { heartbeat_at: number } | undefined;
  return row?.heartbeat_at;
}

/**
 * Picks the next job for the worker. A `running` row can only be left over from a worker that died,
 * so it is replayed first with its attempt number unchanged. Otherwise the oldest eligible queued job
 * is claimed and its attempt count incremented.
 */
export function claimNextJob(db: DatabaseSync, nowMs: number, nowIso: string): JobRecord | undefined {
  return withImmediateTransaction(db, () => {
    const interrupted = one(db, "SELECT * FROM jobs WHERE status = 'running' ORDER BY seq LIMIT 1");
    let seq: number;
    if (interrupted) {
      seq = interrupted.seq;
      db.prepare(
        "UPDATE jobs SET completed_steps = 0, output = NULL, error = NULL, updated_at = ? WHERE seq = ?",
      ).run(nowIso, seq);
    } else {
      const queued = one(db, "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1", nowMs);
      if (!queued) return undefined;
      seq = queued.seq;
      db.prepare(
        `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed_steps = 0,
                         output = NULL, error = NULL, updated_at = ? WHERE seq = ?`,
      ).run(nowIso, seq);
    }
    const row = one(db, 'SELECT * FROM jobs WHERE seq = ?', seq);
    return row && toRecord(row);
  });
}

export function recordProgress(db: DatabaseSync, id: string, completed: number, nowIso: string): void {
  db.prepare("UPDATE jobs SET completed_steps = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(completed, nowIso, id);
}

export function completeJob(db: DatabaseSync, id: string, output: string, nowIso: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'completed', completed_steps = steps, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(output, nowIso, id);
}

export function scheduleRetry(db: DatabaseSync, id: string, availableAtMs: number, nowIso: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'queued', completed_steps = 0, output = NULL, error = NULL, available_at = ?, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(availableAtMs, nowIso, id);
}

export function failJob(db: DatabaseSync, id: string, nowIso: string): void {
  db.prepare(
    "UPDATE jobs SET status = 'failed', completed_steps = 0, output = NULL, error = 'transient failure', updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(nowIso, id);
}

