import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import {
  findJobById,
  findJobByIdemKey,
  insertJob,
  listJobs,
  openDatabase,
  readHeartbeat,
  withImmediateTransaction,
} from './db.ts';
import {
  canonicalPayload,
  parseIdempotencyKey,
  serializeJob,
  validatePayload,
  type FieldError,
  type JobRecord,
  type NewJobPayload,
} from './jobs.ts';

const HEARTBEAT_FRESH_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const SHUTDOWN_GRACE_MS = 3_000;
const SHUTDOWN_HARD_MS = 4_000;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (code === 'invalid_request') error.fields = fields ?? [];
  else if (fields) error.fields = fields;
  send(res, status, { error });
}

function mediaType(header: string | undefined): string {
  return (header ?? '').split(';')[0]!.trim().toLowerCase();
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

function sendHtml(res: ServerResponse): void {
  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(uiHtml);
}

function sendHealth(res: ServerResponse): void {
  const heartbeat = readHeartbeat(db);
  const up = heartbeat !== undefined && Date.now() - heartbeat <= HEARTBEAT_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function sendJobList(res: ServerResponse): void {
  send(res, 200, { jobs: listJobs(db).map(serializeJob) });
}

function sendJob(res: ServerResponse, id: string): void {
  const job = findJobById(db, id);
  if (!job) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, serializeJob(job));
}

type Outcome = { kind: 'created' | 'replay'; job: JobRecord } | { kind: 'conflict' };

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const fields: FieldError[] = [];
  let value: NewJobPayload | undefined;

  if (mediaType(req.headers['content-type']) !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (tooLarge) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    let parsedOk = true;
    try {
      parsed = JSON.parse(text);
    } catch {
      parsedOk = false;
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
    if (parsedOk) {
      const result = validatePayload(parsed);
      fields.push(...result.fields);
      value = result.value;
    }
  }

  const idem = parseIdempotencyKey(req.headers['idempotency-key']);
  if (idem.error) fields.push(idem.error);

  if (fields.length > 0 || value === undefined) {
    return sendError(res, 400, 'invalid_request', 'The submitted job is invalid.', fields);
  }

  const payload = value;
  const payloadKey = canonicalPayload(payload);
  const outcome = withImmediateTransaction<Outcome>(db, () => {
    if (idem.key !== null) {
      const existing = findJobByIdemKey(db, idem.key);
      if (existing) {
        return existing.idemPayload === payloadKey ? { kind: 'replay', job: existing } : { kind: 'conflict' };
      }
    }
    const now = new Date().toISOString();
    const job: JobRecord = {
      seq: 0,
      id: randomUUID(),
      status: 'queued',
      input: payload.input,
      steps: payload.steps,
      failAttempts: payload.failAttempts,
      attempts: 0,
      completedSteps: 0,
      output: null,
      error: null,
      createdAt: now,
      updatedAt: now,
      availableAt: Date.now(),
      idemKey: idem.key,
      idemPayload: idem.key !== null ? payloadKey : null,
    };
    insertJob(db, job);
    return { kind: 'created', job };
  });

  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'created' ? 201 : 200, serializeJob(outcome.job));
}

type Handler = () => void | Promise<void>;

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const method = req.method ?? 'GET';

  let methods: Record<string, Handler> | undefined;
  const jobMatch = /^\/api\/jobs\/([^/]+)$/.exec(path);
  if (path === '/') methods = { GET: () => sendHtml(res) };
  else if (path === '/health') methods = { GET: () => sendHealth(res) };
  else if (path === '/api/jobs') methods = { GET: () => sendJobList(res), POST: () => createJob(req, res) };
  else if (jobMatch) {
    const id = jobMatch[1]!;
    methods = { GET: () => sendJob(res, id) };
  }

  if (!methods) return sendError(res, 404, 'not_found', 'No such route.');
  if (!Object.hasOwn(methods, method)) {
    res.setHeader('Allow', Object.keys(methods).join(', '));
    return sendError(res, 405, 'method_not_allowed', `${method} is not allowed on this route.`);
  }
  await methods[method]!();
}

const server = createServer((req, res) => {
  route(req, res).catch((err: unknown) => {
    console.error('request failed:', err);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.on('error', (err) => {
  console.error('server error:', err);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function finish(): void {
  db.close();
  process.exit(0);
}

function shutdown(signal: NodeJS.Signals): void {
  if (shuttingDown) return;
  shuttingDown = true;
  console.log(`server stopping (${signal})`);
  server.close(finish);
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), SHUTDOWN_GRACE_MS);
  setTimeout(finish, SHUTDOWN_HARD_MS);
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

