import { setTimeout as sleep } from 'node:timers/promises';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  openDatabase,
  recordProgress,
  scheduleRetry,
  writeHeartbeat,
} from './db.ts';
import type { JobRecord } from './jobs.ts';

const STEP_MS = 100;
const IDLE_MS = 100;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

writeHeartbeat(db, Date.now());
const heartbeat = setInterval(() => {
  try {
    writeHeartbeat(db, Date.now());
  } catch (err) {
    console.error('heartbeat failed:', err);
  }
}, HEARTBEAT_MS);

/**
 * Runs one attempt of a job. Progress, retries, and completion are each committed as their own short
 * transaction. If the worker is stopping, the attempt is left `running` and replayed after restart.
 */
async function runAttempt(job: JobRecord): Promise<void> {
  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) return;
    const nowIso = new Date().toISOString();
    if (step === 1 && job.attempts <= job.failAttempts) {
      if (job.attempts < MAX_ATTEMPTS) scheduleRetry(db, job.id, Date.now() + RETRY_DELAY_MS, nowIso);
      else failJob(db, job.id, nowIso);
      return;
    }
    recordProgress(db, job.id, step, nowIso);
  }
  completeJob(db, job.id, job.input.toUpperCase(), new Date().toISOString());
}

function shutdown(signal: NodeJS.Signals): void {
  if (stopping) return;
  stopping = true;
  console.log(`worker stopping (${signal})`);
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => shutdown(signal));
}

console.log('worker started');
while (!stopping) {
  let job: JobRecord | undefined;
  try {
    job = claimNextJob(db, Date.now(), new Date().toISOString());
  } catch (err) {
    console.error('claim failed:', err);
  }
  if (!job) {
    await sleep(IDLE_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (err) {
    console.error(`attempt for job ${job.id} failed:`, err);
    await sleep(IDLE_MS);
  }
}

clearInterval(heartbeat);
clearHeartbeat(db);
db.close();
console.log('worker stopped');
process.exit(0);

